        let mut next = strip.clone();
        next.insert(at, p);
        assert!(is_simple(&next));
        let i = next.iter().position(|q| *q == p).unwrap();
        let n = next.len();
        let nb = [next[(i + n - 1) % n], next[(i + 1) % n]];
        assert!(nb.contains(&vec2(0.1, 1.0)), "should join the closest corner: {:?}", nb);
    }

